void Mubuf::build_modifiers(std::string &out) const {
  auto *inst = &inst_;
  (void)inst;
  if (inst->offen)
    out += " offen";
  if (inst->idxen)
    out += " idxen";
  if (inst->offset)
    out += " offset:" + std::to_string(inst->offset);
  if (inst->sc0)
    out += " sc0";
  if (inst->sc1)
    out += " sc1";
  if (inst->nt)
    out += " nt";
  if (inst->lds)
    out += " lds";
}

